import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('../', import.meta.url))
const output = new URL('../ios/SnapCount/Resources/LocalSharedCompanionPlanner.js', import.meta.url)
const compiled = execFileSync('npx', ['--no-install', 'esbuild',
  'supabase/functions/ingest-receipt/local-shared-planner.ts',
  '--bundle', '--format=iife', '--global-name=JieziSharedPlanner', '--target=safari17', '--minify',
  '--banner:js=// Generated by scripts/generate-ios-companion-planner.mjs. Edit the shared Planner sources.',
], { cwd: root })
if (process.argv.includes('--check')) {
  if (!readFileSync(output).equals(compiled)) {
    throw new Error('Regenerate the iOS Companion Planner with node scripts/generate-ios-companion-planner.mjs')
  }
} else {
  writeFileSync(output, compiled)
}
